patches.replace:
// Cleaning + fixed charges + expenses only. The management fee is deliberately
// NOT in here - it is deducted below, so that Net Earnings can mean "before the
// management fee". The old label claimed the whole of the Elysian charges while
// the fees table above totals those plus the fee: same words, two scopes.
.concat(cleanDeduct>0||fixedCh!==0||exps.length>0 ? [csub(isGR?'Σύνολο χρεώσεων Elysian, εκτός αμοιβής διαχείρισης':'Subtotal — Elysian charges, excl. mgmt fee', -(cleanDeduct+fixedCh+totExp), C_.elySubVat>0 ? -C_.elySubVat : null)] : [])

// The management fee IS an Elysian charge, and it comes off on the next line,
// not this one. Saying "minus ... Elysian charges" here read as though it had.
.concat([cr(L.netEarningsLbl, (isGR?'Μετά από φόρους & χρεώσεις — προ αμοιβής διαχείρισης':'Gross minus taxes, platform fees & Elysian charges — before the management fee'), netEarnings, null, {bold:true, pos:netEarnings>=0, tot:true})])
